import os, json, sys, glob, collections
ROOT = os.path.expanduser('~/.claude/projects')
KEYS = ['Projects-pages', 'orin-dx-site', 'callisto', 'caliper', 'monokl']
WATCH = ['exit-gate', 'auditor', 'verifier', 'adversary', 'reviewer', 'mutator', 'challenger', 'arch-auditor']
out = sys.argv[1]
counts = collections.Counter()
records = []
dirs = [d for d in os.listdir(ROOT) if any(k in d for k in KEYS)]
for d in dirs:
    for f in glob.glob(os.path.join(ROOT, d, '**', '*.jsonl'), recursive=True):
        uses = {}
        try:
            lines = open(f, errors='replace').read().splitlines()
        except Exception:
            continue
        for ln in lines:
            try:
                o = json.loads(ln)
            except Exception:
                continue
            msg = o.get('message') or {}
            c = msg.get('content')
            if not isinstance(c, list):
                continue
            for b in c:
                if not isinstance(b, dict):
                    continue
                if b.get('type') == 'tool_use' and b.get('name') in ('Agent', 'Task'):
                    st = (b.get('input') or {}).get('subagent_type') or ''
                    if ':' in st and any(w in st for w in WATCH):
                        uses[b['id']] = (st, (b.get('input') or {}).get('prompt', '')[:400], o.get('timestamp'))
                elif b.get('type') == 'tool_result' and b.get('tool_use_id') in uses:
                    st, pr, ts = uses[b['tool_use_id']]
                    rc = b.get('content')
                    if isinstance(rc, list):
                        rc = '\n'.join(x.get('text', '') for x in rc if isinstance(x, dict))
                    tur = o.get('toolUseResult') or {}
                    usage = tur.get('usage') if isinstance(tur, dict) else None
                    records.append({'file': f, 'dir': d, 'type': st, 'ts': ts, 'prompt': pr,
                                    'result': rc if isinstance(rc, str) else str(rc),
                                    'tokens': tur.get('totalTokens') if isinstance(tur, dict) else None,
                                    'dur': tur.get('totalDurationMs') if isinstance(tur, dict) else None,
                                    'tools': tur.get('totalToolUseCount') if isinstance(tur, dict) else None})
                    counts[st] += 1
json.dump(records, open(out, 'w'), indent=1)
for k, v in counts.most_common():
    print(v, k)
print('dirs', len(dirs), 'records', len(records))

