import json, glob, os, sys, re
d = sys.argv[1]
def key(p):
    m = re.match(r'(.*)-verdict(?:-(\d+))?\.json', os.path.basename(p))
    return (m.group(1), int(m.group(2) or 1))
for p in sorted(glob.glob(os.path.join(d, '*verdict*.json')), key=key):
    v = json.load(open(p))
    bl = v.get('blockers') or []
    print('##', os.path.basename(p), v.get('verdict') or v.get('status') or v.get('passed'), 'blockers', len(bl), 'gaps', len(v.get('coverage_gaps') or []), 'pending', len(v.get('pending_checks') or []))
    for b in bl:
        if isinstance(b, dict):
            s = b.get('description') or b.get('issue') or b.get('reason') or json.dumps(b)
        else:
            s = str(b)
        print('  -', s[:int(sys.argv[2]) if len(sys.argv) > 2 else 260].replace('\n', ' '))

